SELECT a.slug, a.status, (SELECT jsonb_agg(jsonb_build_object('locale', d.locale, 'revision', d.revision, 'status', d.status) ORDER BY d.locale) FROM public.editorial_documents d WHERE d.owner_artist_id = a.id AND d.document_type = 'artist_biography') AS documents, (SELECT count(*) FROM public.editorial_entity_references r JOIN public.editorial_documents d ON d.id = r.editorial_document_id WHERE d.owner_artist_id = a.id AND d.document_type = 'artist_biography') AS reference_count FROM public.artists a WHERE a.id = '79d013c7-dafc-4807-966e-32c370172dee'::uuid;

