SELECT a.slug, a.status, (SELECT jsonb_agg(jsonb_build_object('locale', d.locale, 'revision', d.revision, 'status', d.status) ORDER BY d.locale) FROM public.editorial_documents d WHERE d.owner_artist_id = a.id AND d.document_type = 'artist_biography') AS documents, (SELECT count(*) FROM public.editorial_entity_references r JOIN public.editorial_documents d ON d.id = r.editorial_document_id WHERE d.owner_artist_id = a.id AND d.document_type = 'artist_biography') AS reference_count FROM public.artists a WHERE a.id = '0eb60cd0-a128-40e0-af30-6b3d0dd95bf6'::uuid;

-- 7 of 10: adriano-ventura
DO $editorial_pass$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.artists WHERE id = '7bc2d1c9-baa4-4928-86f1-bbd0168fdf7c'::uuid AND slug = 'adriano-ventura' AND status = 'published' AND bio_en IS NOT DISTINCT FROM 'Adriano Ventura —born in the Santiago suburb of Jacagua, one of nine musical siblings that included his sister Aridia Ventura— is a Dominican bachata singer and composer remembered as one of the genre’s earliest pioneers, and as the first bachata artist Santiago produced.

**«La Novia Ajena»**

In 1968 he wrote and recorded «La Novia Ajena», a bachata composed in the style and rhythm of the Mexican vals, which brought him considerable success in a genre then still taking shape alongside foundational figures like José Manuel Calderón and Luis Segura.

**Launching his sister’s career**

In 1975 he produced Aridia Ventura’s first single, helping launch a career that would make her one of bachata’s leading female voices — even though he and others had reservations when she went on to sign a five-year contract with Radhamés Aracena of Radio Guarachita.

**Legacy**

Still remembered today as the first bachatero Santiago ever produced, Adriano Ventura now lives in Manhattan, New York.' AND bio_es IS NOT DISTINCT FROM 'Adriano Ventura —nacido en el suburbio de Jacagua, Santiago, uno de nueve hermanos músicos entre los que se encontraba su hermana Aridia Ventura— es cantante y compositor dominicano de bachata, recordado como uno de los pioneros más tempranos del género y como el primer bachatero que tuvo Santiago.

**«La Novia Ajena»**

En 1968 escribió y grabó «La Novia Ajena», una bachata compuesta al estilo y ritmo del vals mexicano, que le dio un éxito considerable en un género que todavía se formaba junto a figuras fundacionales como José Manuel Calderón y Luis Segura.

**El impulso a la carrera de su hermana**

En 1975 produjo el primer sencillo de Aridia Ventura, ayudando a lanzar una carrera que la convertiría en una de las voces femeninas líderes de la bachata — aunque él y otros tuvieron reservas cuando ella firmó después un contrato de cinco años con Radhamés Aracena de Radio Guarachita.

**Legado**

Recordado todavía hoy como el primer bachatero que tuvo Santiago, Adriano Ventura reside actualmente en Manhattan, Nueva York.' AND genres IS NOT DISTINCT FROM ARRAY['bachata','merengue']::text[] AND occupations IS NOT DISTINCT FROM '["singer","songwriter","bandleader","producer","musician"]'::jsonb FOR UPDATE) THEN
    RAISE EXCEPTION 'Stale artist or mirror precondition: adriano-ventura';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.editorial_documents WHERE id = 'dbf49ffa-7e43-44ba-9782-05b7a79b9135'::uuid AND owner_artist_id = '7bc2d1c9-baa4-4928-86f1-bbd0168fdf7c'::uuid AND locale = 'en' AND status = 'published' AND revision = 2 AND document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Adriano Ventura —born in the Santiago suburb of Jacagua, one of nine musical siblings that included his sister ","type":"text"},{"type":"artistReference","attrs":{"artistId":"01db8904-c39e-428d-bbea-da4049a79ee6","displayText":"Aridia Ventura","occurrenceId":"de2b0adf-bee3-47de-8b3b-541a5fce3c3e"}},{"text":"— is a Dominican bachata singer and composer remembered as one of the genre’s earliest pioneers, and as the first bachata artist Santiago produced.","type":"text"}]},{"type":"paragraph","content":[{"text":"«La Novia Ajena»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1968 he wrote and recorded «La Novia Ajena», a bachata composed in the style and rhythm of the Mexican vals, which brought him considerable success in a genre then still taking shape alongside foundational figures like ","type":"text"},{"type":"artistReference","attrs":{"artistId":"27c82e93-8c8f-4466-86ab-e1afba1e5487","displayText":"José Manuel Calderón","occurrenceId":"44fcacbc-2244-4ebb-9dad-1f674d06802c"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura","occurrenceId":"136bdaea-dd17-4614-b61b-a1ef476e7ea1"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Launching his sister’s career","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1975 he produced Aridia Ventura’s first single, helping launch a career that would make her one of bachata’s leading female voices — even though he and others had reservations when she went on to sign a five-year contract with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a08ab62e-ec7b-4770-ae52-60c1fcea6a08","displayText":"Radhamés Aracena","occurrenceId":"7cc96040-8137-47f9-a38a-74fdb025c3ed"}},{"text":" of Radio Guarachita.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Still remembered today as the first bachatero Santiago ever produced, Adriano Ventura now lives in Manhattan, New York.","type":"text"}]}]}'::jsonb FOR UPDATE) THEN
