  IF NOT EXISTS (SELECT 1 FROM public.editorial_documents WHERE id = 'ce7f26f9-3a9e-43bc-9b6d-7244f0d3edca'::uuid AND owner_artist_id = '7bc2d1c9-baa4-4928-86f1-bbd0168fdf7c'::uuid AND locale = 'es' AND status = 'published' AND revision = 1 AND document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Adriano Ventura —nacido en el suburbio de Jacagua, Santiago, uno de nueve hermanos músicos entre los que se encontraba su hermana ","type":"text"},{"type":"artistReference","attrs":{"artistId":"01db8904-c39e-428d-bbea-da4049a79ee6","displayText":"Aridia Ventura","occurrenceId":"57b5ed97-7e06-4f53-a325-444d8e177761"}},{"text":"— es cantante y compositor dominicano de bachata, recordado como uno de los pioneros más tempranos del género y como el primer bachatero que tuvo Santiago.","type":"text"}]},{"type":"paragraph","content":[{"text":"«La Novia Ajena»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1968 escribió y grabó «La Novia Ajena», una bachata compuesta al estilo y ritmo del vals mexicano, que le dio un éxito considerable en un género que todavía se formaba junto a figuras fundacionales como ","type":"text"},{"type":"artistReference","attrs":{"artistId":"27c82e93-8c8f-4466-86ab-e1afba1e5487","displayText":"José Manuel Calderón","occurrenceId":"1a0d78aa-6752-4f87-9832-fb6252fe3121"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5ceceef0-765d-4e01-8017-85422a263357","displayText":"Luis Segura","occurrenceId":"07adfe6b-21e4-4aa4-8859-44b3e0750364"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"El impulso a la carrera de su hermana","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1975 produjo el primer sencillo de Aridia Ventura, ayudando a lanzar una carrera que la convertiría en una de las voces femeninas líderes de la bachata — aunque él y otros tuvieron reservas cuando ella firmó después un contrato de cinco años con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a08ab62e-ec7b-4770-ae52-60c1fcea6a08","displayText":"Radhamés Aracena","occurrenceId":"b6a9c077-783a-4851-877a-db56f926b764"}},{"text":" de Radio Guarachita.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Recordado todavía hoy como el primer bachatero que tuvo Santiago, Adriano Ventura reside actualmente en Manhattan, Nueva York.","type":"text"}]}]}'::jsonb FOR UPDATE) THEN
